question:
There are two colors Jessica can use to color this 2 by 2 grid. If non-overlapping regions that share a side cannot be the same color, how many possible ways are there for Jessica to color the grid?

[asy]
size(101);
draw(unitsquare);
draw((0,.5)--(1,.5));
draw((.5,0)--(.5,1));
label("$A$",(0,1),NW); label("$B$",(1,1),NE); label("$C$",(1,0),SE); label("$D$",(0,0),SW);
[/asy]

teacher_action.code_action:
count = 0
colors = [0, 1] # 0 and 1 represent the two colors
for c_A in colors:
    for c_B in colors:
        for c_C in colors:
            for c_D in colors:
                # Check adjacencies: A-B, B-C, C-D, D-A
                if c_A != c_B and c_B != c_C and c_C != c_D and c_D != c_A:
                    count += 1
print(f"Number of valid colorings: {count}")

