def is_composite(n):
    """Check if a number is composite (has two or more prime factors)"""
    if n <= 1:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False
    for i in range(3, int(n**0.5) + 1, 2):
        if n % i == 0:
            return True
    return False

# Find all composite numbers less than 87
