def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def is_multiple_of_power(m, n):
    """Check if m^m is a multiple of n^n"""
    # We need to check if for every prime p dividing n with exponent a,
    # the exponent of p in m^m is at least n*a
    # i.e., m * v_p(m) >= n * v_p(n) for all primes p

    def prime_factorization(x):
        factors = {}
        d = 2
        temp = x
        while d * d <= temp:
            while temp % d == 0:
                factors[d] = factors.get(d, 0) + 1
                temp //= d
            d += 1
        if temp > 1:
            factors[temp] = factors.get(temp, 0) + 1
        return factors

    n_factors = prime_factorization(n)
    m_factors = prime_factorization(m)

    for p, exp_n in n_factors.items():
        exp_m = m_factors.get(p, 0)
        # Need m * exp_m >= n * exp_n
        if m * exp_m < n * exp_n:
            return False
    return True

# Search for smallest m+n
min_sum = float('inf')
best_pair = None

for s in range(1, 500):  # Check sums up to 500
    if gcd(s, 210) != 1:
        continue
    for n in range(1, s):
        m = s - n
        if m <= 0:
            continue
        # Check if m is not a multiple of n
        if m % n == 0:
            continue
        # Check if m^m is a multiple of n^n
        if is_multiple_of_power(m, n):
            if s < min_sum:
                min_sum = s
                best_pair = (m, n)
            break  # Found a valid pair for this sum, move to next sum

print(f"Minimum sum: {min_sum}")
print(f"Best pair (m, n): {best_pair}")

