# Define Gaussian integers as tuples (a, b) representing a + bi
def add_gauss(z1, z2):
    return (z1[0] + z2[0], z1[1] + z2[1])

def mul_gauss(z1, z2):
    # (a+bi)(c+di) = (ac-bd) + (ad+bc)i
    return (z1[0]*z2[0] - z1[1]*z2[1], z1[0]*z2[1] + z1[1]*z2[0])

def conj_gauss(z):
    return (z[0], -z[1])

def norm_gauss(z):
    return z[0]**2 + z[1]**2

# Generate all divisors of 50 in Z[i]
# 50 = 2 * 5^2 = (1+i)(1-i) * (2+i)(2-i) * (2+i)(2-i) ?
# Actually 2 = -i(1+i)^2. 5 = (2+i)(2-i).
# So 50 = -i * (1+i)^2 * (2+i)^2 * (2-i)^2.
# Divisors are u * (1+i)^a * (2+i)^b * (2-i)^c
# where u in {1, i, -1, -i}, 0<=a<=2, 0<=b<=2, 0<=c<=2.

units = [(1, 0), (0, 1), (-1, 0), (0, -1)]
p1 = (1, 1) # 1+i
p2 = (2, 1) # 2+i
p3 = (2, -1) # 2-i

divisors = set()
for u in units:
    for a in range(3):
        for b in range(3):
            for c in range(3):
                d = u
                for _ in range(a):
                    d = mul_gauss(d, p1)
                for _ in range(b):
                    d = mul_gauss(d, p2)
                for _ in range(c):
                    d = mul_gauss(d, p3)
                divisors.add(d)

