# Let's verify by checking if 50/d is in Z[i].
# 50 is (50, 0).
target = (50, 0)
valid_divisors = []
for d in divisors:
    # Check if target / d is a Gaussian integer
    # (x+yi)/(a+bi) = ((x+yi)(a-bi))/(a^2+b^2)
    num_real = target[0]*d[0] + target[1]*d[1]
    num_imag = target[1]*d[0] - target[0]*d[1]
    den = norm_gauss(d)
