from itertools import permutations

edge_lengths = [7, 13, 18, 27, 36]
AB = 41

def check_triangle_inequality(a, b, c):
    """Check if three lengths can form a triangle."""
    return (a + b > c) and (a + c > b) and (b + c > a)

def is_valid_tetrahedron(AC, AD, BC, BD, CD):
    """Check if all four faces satisfy triangle inequality."""
    # Face ABC: AB, AC, BC
    if not check_triangle_inequality(AB, AC, BC):
        return False
    # Face ABD: AB, AD, BD  
    if not check_triangle_inequality(AB, AD, BD):
        return False
    # Face ACD: AC, AD, CD
    if not check_triangle_inequality(AC, AD, CD):
        return False
    # Face BCD: BC, BD, CD
    if not check_triangle_inequality(BC, BD, CD):
        return False
    return True

# Try each possible value for CD
possible_CD_values = []

for CD in edge_lengths:
    remaining_edges = [e for e in edge_lengths if e != CD]
    # We need to assign remaining_edges to AC, AD, BC, BD
    found_valid = False
    for perm in permutations(remaining_edges):
        AC, AD, BC, BD = perm
        if is_valid_tetrahedron(AC, AD, BC, BD, CD):
            possible_CD_values.append(CD)
            found_valid = True
            break  # Found at least one valid assignment for this CD

    if found_valid:
        print(f"CD = {CD} is possible")
    else:
        print(f"CD = {CD} is NOT possible")

print(f"\nPossible values for CD: {possible_CD_values}")

