# Let's verify by counting triangles directly
# Vertices are (x, y) where 1 <= x <= 4 and 1 <= y <= 4

count = 0
valid_triangles = []

for x in range(1, 5):
    for y in range(1, 5):
        # Check if there exists another point (x', y') such that the triangle has positive area
        # This means the three points are not collinear

        # Check if collinear with (x, y)
        # Collinear if (x', y') lies on the line through (x, y) with integer coefficients
        # The line equation can be written as a*x + b*y + c = 0
        # For integer points, this means a*x + b*y + c = 0 for some integers a, b, c

        # Actually, let's check if the determinant condition holds
        # Or simpler: check if they are on the same line

        # Check vertical lines: x = c
        for c in range(1, 5):
            if x == c:
                for y in range(1, 5):
                    for y2 in range(1, 5):
                        if y != y2:
                            count += 1
                            valid_triangles.append((x, y, y2))

        # Check horizontal lines: y = c
        for c in range(1, 5):
            if y == c:
                for x in range(1, 5):
                    for x2 in range(1, 5):
                        if x != x2:
                            count += 1
                            valid_triangles.append((x, y, x2))

        # Check diagonal lines: y - x = k
        # k can be 0, 1, -1
        for k in range(-1, 2):
            if y - x == k:
                for x2 in range(1, 5):
                    if x != x2 and y != y2:
                        count += 1
                        valid_triangles.append((x, y, x2))

        # Check other diagonal lines: y - x = 1
        if y - x == 1:
            for x2 in range(1, 5):
                if x != x2 and y != y2:
                    count += 1
                    valid_triangles.append((x, y, x2))

        # Check other diagonal lines: y - x = -1
        if y - x == -1:
            for x2 in range(1, 5):
                if x != x2 and y != y2:
                    count += 1
                    valid_triangles.append((x, y, x2))

print(f"Total triangles: {count}")
print(f"Valid triangles: {valid_triangles}")
print(f"Number of valid triangles: {count}")

# Let's also verify the formula approach
total_points = 16
collinear_vertical = 4 * 4  # 4 lines * 4 points each
collinear_horizontal = 4 * 4  # 4 lines * 4 points each
collinear_diagonal = 2 * 4  # 2 lines * 4 points each
collinear_total = collinear_vertical + collinear_horizontal + collinear_diagonal
positive_area = total_points - collinear_total
print(f"Total points: {total_points}")
print(f"Collinear vertical: {collinear_vertical}")
print(f"Collinear horizontal: {collinear_horizontal}")
print(f"Collinear diagonal: {collinear_diagonal}")
print(f"Collinear total: {collinear_total}")
print(f"Positive area: {positive_area}")

